	return filepath.Join(repoRoot, ".opencode", pluginDirName, pluginFileName), nil
}

// InstallHooks writes the Entire plugin file to .opencode/plugins/entire.ts.
// Returns 1 if the plugin was written, 0 if already up-to-date (idempotent).
// If the file exists but content differs (e.g., localDev vs production), it is rewritten.
func (a *OpenCodeAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
	pluginPath, err := getPluginPath(ctx)
	if err != nil {
		return 0, err
	}

	// Build the command prefix
	var cmdPrefix string
	if localDev {
		cmdPrefix = `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go`
	} else {
		cmdPrefix = "entire"
	}

	// Generate plugin content from template
	content := strings.ReplaceAll(pluginTemplate, entireCmdPlaceholder, cmdPrefix)
	content = strings.ReplaceAll(content, entireWarningPlaceholder, agent.EntireNotInstalledWarning)

	// Check if already installed with identical content (idempotent) unless force
	if !force {
		if existing, readErr := os.ReadFile(pluginPath); readErr == nil { //nolint:gosec // Path constructed from repo root
			if string(existing) == content {
				return 0, nil // Already up-to-date
			}
		}
	}

	// Ensure directory exists
	pluginDir := filepath.Dir(pluginPath)
	//nolint:gosec // G301: Plugin directory needs standard permissions
	if err := os.MkdirAll(pluginDir, 0o755); err != nil {
		return 0, fmt.Errorf("failed to create plugin directory: %w", err)
	}

	// Write plugin file
	//nolint:gosec // G306: Plugin file needs standard permissions for OpenCode to read
	if err := os.WriteFile(pluginPath, []byte(content), 0o644); err != nil {
		return 0, fmt.Errorf("failed to write plugin file: %w", err)
	}

	return 1, nil
}

// UninstallHooks removes the Entire plugin file.
func (a *OpenCodeAgent) UninstallHooks(ctx context.Context) error {
	pluginPath, err := getPluginPath(ctx)
	if err != nil {
		return err
	}

	if err := os.Remove(pluginPath); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to remove plugin file: %w", err)
	}

	return nil
}

// AreHooksInstalled checks if the Entire plugin file exists and contains the marker.
func (a *OpenCodeAgent) AreHooksInstalled(ctx context.Context) bool {
	pluginPath, err := getPluginPath(ctx)
	if err != nil {
		return false
	}

	data, err := os.ReadFile(pluginPath) //nolint:gosec // Path constructed from repo root
	if err != nil {
		return false
	}

	return strings.Contains(string(data), entireMarker)
}

